input.command:
cat > /tmp/lamp22-probe.mjs <<'EOF'
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const g = load(process.argv[2]);
for (const y of [9, 8, 7, 6, 5]) {
  const row = [];
  for (let z = 13; z <= 17; z++) {
    const cells = [];
    for (let x = 25; x <= 29; x++) cells.push(String(g.get?.(x, y, z)?.[0] ?? g.at?.(x, y, z) ?? "?").padEnd(16));
    row.push(`z${z}: ${cells.join(" | ")}`);
  }
  console.log(`y${y}\n  ` + row.join("\n  "));
}
EOF
node /tmp/lamp22-probe.mjs build.nbt 2>&1 | head -40; grep -n "export" /Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs | head -5; grep -n "^  get\|^  at\|^  block\|^  set(" /Volumes/ext1/swe/repos/minecraft-design/tools/src/*.mjs | head

